# 45 beer brands: (slug, name, url, verified fact, observation 1, observation 2, slide notes [(text, fx, fy)])
# Notes are filled in from notes.json once the logos are placed.
import json, os
_N = json.load(open(os.path.join(os.path.dirname(__file__), 'notes.json'))) if os.path.exists(os.path.join(os.path.dirname(__file__), 'notes.json')) else {}
_B = [
("budweiser","Budweiser","https://www.budweiser.com/","Anheuser-Busch introduced Budweiser in St. Louis in 1876.","The script lettering comes straight from the classic bottle label.","The red bowtie shape gives the brand a symbol that works even without words."),
("heineken","Heineken","https://www.heineken.com/","Gerard Adriaan Heineken bought the Haystack brewery in Amsterdam in 1864.","The lowercase \"e\" letters are tilted back, which is often described as making the logo look like it is smiling.","The red star and green colour are recognised in bars all over the world."),
("corona","Corona","https://www.corona.com/","Cervecería Modelo launched Corona in Mexico City in 1925.","The crown is a direct picture of the name, which means crown in Spanish.","Blue lettering and a gold crown make the label feel sunny and relaxed, like the beach ads."),
("stella-artois","Stella Artois","https://www.stellaartois.com/","Stella Artois was first brewed as a Christmas beer in Leuven, Belgium, in 1926, and the brewery traces its roots to 1366.","The star in the name (Stella means star in Latin) sits above the wordmark like a seal.","The ornate border and the 1366 date make it look like an old European crest."),
("guinness","Guinness","https://www.guinness.com/","Arthur Guinness signed a 9,000-year lease on the St. James's Gate brewery in Dublin in 1759.","The harp is based on the medieval Brian Boru harp and was registered as a trademark in 1876.","The harp faces right, the opposite way from the harp on the Irish state seal."),
("carlsberg","Carlsberg","https://www.carlsberg.com/","J.C. Jacobsen founded Carlsberg in Copenhagen in 1847 and named it after his son Carl.","The flowing script was drawn in 1904 by the architect Thorvald Bindesbøll.","A small crown and hop leaf sit above the name."),
("coors-light","Coors Light","https://www.coorslight.com/","Adolph Coors founded his brewery in Golden, Colorado, in 1873, and Coors Light launched in 1978.","Mountains in the logo point to the Rocky Mountains and the idea of cold, fresh water.","Red Coors script over a silver LIGHT keeps the classic family name in front."),
("miller-lite","Miller Lite","https://www.millerlite.com/","Miller Lite launched nationally in 1975, one of the first successful light beers in the US.","The retro wordmark brought back the brand's original 1970s look in 2014.","The small Miller crest under the word Lite keeps the link to the parent brewery."),
("michelob-ultra","Michelob Ultra","https://www.michelobultra.com/","Anheuser-Busch launched Michelob Ultra in 2002 as a low-carb beer.","The thin, spaced capitals feel sporty and clean, like a fitness brand.","A small crest above the Michelob script keeps the link to the older parent brand."),
("pilsner-urquell","Pilsner Urquell","https://www.pilsnerurquell.com/","Pilsner Urquell was first brewed in Plzeň, in today's Czech Republic, in 1842, and it was the first golden pilsner.","The seal with the brewery gate shows the building where pilsner was invented.","Urquell means \"original source\" in German, so the name itself is a claim to be first."),
("becks","Beck's","https://becks.com/","Heinrich Beck and partners founded the Beck's brewery in Bremen, Germany, in 1873.","The key comes from the coat of arms of Bremen.","The white, red and green label makes the bottle easy to spot from across a bar."),
("peroni","Peroni","https://www.peroni.com/","Francesco Peroni started brewing in Vigevano, Italy, in 1846 and moved the brewery to Rome in 1864.","Heavy red capitals inside a gold frame look like a classic Italian label.","Its export lager, Nastro Azzurro, means \"blue ribbon\"."),
("amstel","Amstel","https://www.amstel.com/","Amstel was founded in Amsterdam in 1870 and named after the river Amstel.","Bold red capitals on a white field are simple and easy to read.","The coat-of-arms style badge suggests a long Dutch brewing tradition."),
("hoegaarden","Hoegaarden","https://www.hoegaarden.com/","Pierre Celis revived Belgian witbier in the village of Hoegaarden in 1966.","Heavy, curly lettering looks hand-painted, like an old village sign.","The deep blue colour matches the brand's cloudy white beer and its blue glassware."),
("paulaner","Paulaner","https://www.paulaner.com/","Paulaner traces its history to the monks of the Neudeck ob der Au monastery in Munich in 1634.","The portrait shows Saint Francis of Paola, the founder of the monks' order.","The circular badge looks like a monastery seal, which tells the origin story at a glance."),
("grolsch","Grolsch","https://www.grolsch.com/","Grolsch dates its brewing to 1615 in Groenlo, in the Netherlands.","The bouncy script reads like a signature, which makes the brand feel personal.","The brand is equally famous for its swing-top bottle, which the logo often appears on."),
("duvel","Duvel","https://www.duvel.com/","The Moortgat family brewery in Belgium has made Duvel since the 1920s; the name means \"devil\" in local dialect.","Heavy red letters with sharp serifs look bold, a hint at how strong the beer is.","The name is a joke about the strength of the beer, and the logo leans into it with confident type."),
("chimay","Chimay","https://chimay.com/","Trappist monks at Scourmont Abbey in Chimay, Belgium, have brewed beer since 1862.","The logo shows the abbey's coat of arms, so the monks' authority is built into it.","Serif capitals and a red seal look like an official mark of origin."),
("asahi","Asahi","https://www.asahibeer.com/","Asahi traces its history to the Osaka Beer Company, founded in 1889, and Asahi Super Dry launched in 1987.","Sharp, slanted capitals look fast and crisp, like the \"dry\" taste the brand promises.","The silver and black colours of Super Dry feel modern and Japanese."),
("kirin","Kirin","https://www.kirin.com/","Kirin beer was first sold in Japan in 1888.","Bold red capitals keep the company name simple and strong.","On the beer labels the brand also uses the kirin, a mythical creature with katakana characters hidden in its mane."),
("sapporo","Sapporo","https://www.sapporobeer.com/","Sapporo beer was first brewed in Sapporo, Japan, in 1876.","The star comes from the pioneer star of Hokkaido, the island where Sapporo is.","The star is large and the name small, so the symbol does most of the work."),
("tsingtao","Tsingtao","https://www.tsingtao.com.cn/","German and British settlers founded the Tsingtao brewery in Qingdao, China, in 1903.","The badge shows the Zhan Qiao pier, a famous landmark in Qingdao.","The green colour and the old spelling of the city name tell you where the beer comes from."),
("tiger","Tiger","https://www.tigerbeer.com/","Tiger beer was first brewed in Singapore in 1932.","The tiger symbol is a direct picture of the name.","The tiger leaps over the letters, so the symbol and the name form one lockup."),
("singha","Singha","https://www.singha.com/","Boon Rawd Brewery launched Singha in Thailand in 1934.","The lion is the Singha, a lion from Thai and Hindu mythology.","The lion sits in a round seal with a ribbon, like an official emblem."),
("modelo","Modelo","https://www.modelousa.com/","Cervecería Modelo was founded in Mexico City in 1925, and Modelo Especial launched the same year.","Tall, condensed letters with a small arched \"Cerveza\" above look like a classic label.","Deep navy makes a mass-market beer feel premium."),
("dos-equis","Dos Equis","https://www.dosequis.com/","German brewer Wilhelm Hasse created Dos Equis in Mexico in 1897.","The two X letters were meant to celebrate the start of the 20th century.","The simple XX symbol works alone on bottle caps and tap handles."),
("tecate","Tecate","https://www.tecate.com/","Tecate was first brewed in the town of Tecate, Baja California, in 1944.","The heavy, condensed capitals are one of the boldest wordmarks in beer.","The wide, flat letters stay readable on red cans from across a room."),
("sierra-nevada","Sierra Nevada","https://sierranevada.com/","Ken Grossman founded Sierra Nevada in Chico, California, in 1980.","The mountain scene shows the Sierra Nevada range the brewery is named after.","The illustrated landscape feels outdoorsy and natural, a big part of the brand's craft image."),
("samuel-adams","Samuel Adams","https://www.samueladams.com/","Jim Koch founded the Boston Beer Company in 1984 and named the beer after the patriot Samuel Adams.","Old-style serif capitals look like 18th-century printing.","The stacked name puts the revolutionary patriot himself at the centre of the brand."),
("lagunitas","Lagunitas","https://lagunitas.com/","Tony Magee founded Lagunitas in Lagunitas, California, in 1993.","Heavy, tightly packed capitals look like an old handbill.","The smaller BREWING COMPANY line underneath adds a pop of red."),
("dogfish-head","Dogfish Head","https://www.dogfish.com/","Sam Calagione opened Dogfish Head in Rehoboth Beach, Delaware, in 1995.","The dogfish shark is a playful picture of the name.","Bold, chunky letters match the brewery's experimental, offbeat beers."),
("stone-brewing","Stone Brewing","https://www.stonebrewing.com/","Greg Koch and Steve Wagner founded Stone Brewing in San Diego in 1996.","The gargoyle is the brewery's guardian, said to keep bad spirits away from the beer.","The dark, aggressive style suits the brand's strong, hoppy beers."),
("new-belgium","New Belgium","https://www.newbelgium.com/","Jeff Lebesch and Kim Jordan founded New Belgium in Fort Collins, Colorado, in 1991.","The bicycle comes from the brewery's famous Fat Tire beer, named after a bike trip in Belgium.","The friendly, rounded style makes the brand feel approachable."),
("goose-island","Goose Island","https://www.gooseisland.com/","John Hall opened Goose Island as a brewpub in Chicago in 1988.","The flying goose is a simple picture of the name, from an island in the Chicago River.","The badge shape looks like a classic brewery sign."),
("brooklyn-brewery","Brooklyn Brewery","https://brooklynbrewery.com/","Steve Hindy and Tom Potter founded Brooklyn Brewery in 1988, and Milton Glaser designed the logo.","The B inside a circle looks like the logo of a baseball team, which was Glaser's idea.","Glaser, who also created I ♥ NY, was paid partly in a share of the company."),
("founders","Founders","https://foundersbrewing.com/","Mike Stevens and Dave Engbers founded Founders in Grand Rapids, Michigan, in 1997.","Hand-drawn script inside an oval looks like a classic beer label.","The brewery's slogan \"Brewed for us\" sits behind a plain, confident mark."),
("brewdog","BrewDog","https://www.brewdog.com/","James Watt and Martin Dickie founded BrewDog in Fraserburgh, Scotland, in 2007.","The wordmark is set in a heavy, stencil-like style that feels loud and rebellious.","The dog in the name and logo comes from the founders' dog, Bracken."),
("mikkeller","Mikkeller","https://mikkeller.com/","Mikkel Borg Bjergsø founded Mikkeller in Copenhagen in 2006 as a \"gypsy\" brewer without a brewery of his own.","The cartoon characters drawn by Keith Shore became as famous as the beer.","The simple logo lets the colourful label art do most of the work."),
("omnipollo","Omnipollo","https://omnipollo.com/","Brewer Henok Fentie and artist Karl Grandin founded Omnipollo in Stockholm in 2011.","The logo is minimal, because Grandin's surreal label art is the real brand.","The name sounds playful and international, matching the experimental beers."),
("athletic-brewing","Athletic Brewing","https://athleticbrewing.com/","Bill Shufelt and John Walker founded Athletic Brewing in Connecticut in 2017 to make non-alcoholic craft beer.","The round club badge with an A looks like a sports team crest.","Clean lettering looks like an outdoor gear brand, not a typical beer label."),
("beavertown","Beavertown","https://beavertownbrewery.co.uk/","Logan Plant founded Beavertown in London in 2011.","A skull replaces the O, adding a little punk to a friendly name.","Artist Nick Dwyer's colourful, cosmic label art made the brewery stand out in UK shops."),
("cloudwater","Cloudwater","https://cloudwaterbrew.co/","Paul Jones and James Campbell founded Cloudwater in Manchester in 2015.","A round badge with a cloud above water is a literal picture of the name.","The brand changes its can designs every season, so the simple badge has to stay constant."),
("other-half","Other Half","https://otherhalfbrewing.com/","Sam Richardson, Matt Monahan and Andrew Burman opened Other Half in Brooklyn in 2014.","Two overlapping rings show two halves becoming one.","Widely spaced capitals feel calm and modern next to the brewery's loud can art."),
("garage-project","Garage Project","https://garageproject.co.nz/","Garage Project started brewing in a former petrol station in Wellington, New Zealand, in 2011.","The arched lettering looks like an old workshop sign, complete with the Aro Street address.","The badge feels handmade, which suits a brewery known for strange experiments."),
("to-ol","To Øl","https://toolbeer.dk/","Tobias Emil Jensen and Tore Gynther founded To Øl in Copenhagen in 2010.","The name means \"two beers\" in Danish, and the logo puts the Ø front and centre.","The black box makes the logo look like a label or a stamp."),
]
B = [t + (_N.get(t[0], []),) for t in _B]
assert len(B) == 45
